create or replace function private.notes_can_edit_folder(p_folder_id uuid,p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$
select p_folder_id is not null and (exists(with recursive ancestors(id,parent_folder_id,owner_id) as (select f.id,f.parent_folder_id,f.owner_id from public.notes_folders f where f.id=p_folder_id union all select parent.id,parent.parent_folder_id,parent.owner_id from public.notes_folders parent join ancestors a on a.parent_folder_id=parent.id) select 1 from ancestors a where a.owner_id=p_user_id)
or exists(with recursive ancestors(id,parent_folder_id) as (select f.id,f.parent_folder_id from public.notes_folders f where f.id=p_folder_id union all select parent.id,parent.parent_folder_id from public.notes_folders parent join ancestors a on a.parent_folder_id=parent.id) select 1 from public.notes_collaborators c join ancestors a on a.id=c.folder_id where c.resource_type='FOLDER' and c.invited_user_id=p_user_id and c.status='ACCEPTED'));$$;
create or replace function private.notes_can_manage_folder(p_folder_id uuid,p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$
select p_folder_id is not null and exists(with recursive ancestors(id,parent_folder_id,owner_id) as (select f.id,f.parent_folder_id,f.owner_id from public.notes_folders f where f.id=p_folder_id union all select parent.id,parent.parent_folder_id,parent.owner_id from public.notes_folders parent join ancestors a on a.parent_folder_id=parent.id) select 1 from ancestors a where a.owner_id=p_user_id);$$;
create or replace function private.notes_can_edit_document(p_document_id uuid,p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$
select p_document_id is not null and (exists(select 1 from public.notes_documents d where d.id=p_document_id and d.owner_id=p_user_id) or (not private.notes_is_platform_owner(p_user_id) and (exists(select 1 from public.notes_collaborators c where c.resource_type='DOCUMENT' and c.document_id=p_document_id and c.invited_user_id=p_user_id and c.status='ACCEPTED') or exists(select 1 from public.notes_documents d where d.id=p_document_id and d.folder_id is not null and private.notes_can_edit_folder(d.folder_id,p_user_id)))));$$;
drop policy notes_folders_insert_access on public.notes_folders;
create policy notes_folders_insert_access on public.notes_folders for insert to authenticated with check(owner_id=(select auth.uid()) and (parent_folder_id is null or private.notes_can_edit_folder(parent_folder_id,(select auth.uid()))));
drop policy notes_folders_update_owner on public.notes_folders;
create policy notes_folders_update_owner on public.notes_folders for update to authenticated using(private.notes_can_manage_folder(id,(select auth.uid()))) with check(private.notes_can_manage_folder(id,(select auth.uid())));
drop policy notes_folders_delete_owner on public.notes_folders;
create policy notes_folders_delete_owner on public.notes_folders for delete to authenticated using(private.notes_can_manage_folder(id,(select auth.uid())));
drop policy notes_documents_insert_access on public.notes_documents;
create policy notes_documents_insert_access on public.notes_documents for insert to authenticated with check(owner_id=(select auth.uid()) and (folder_id is null or private.notes_can_edit_folder(folder_id,(select auth.uid()))));
drop policy notes_documents_delete_owner on public.notes_documents;
create policy notes_documents_delete_owner on public.notes_documents for delete to authenticated using(owner_id=(select auth.uid()) or (folder_id is not null and private.notes_can_manage_folder(folder_id,(select auth.uid()))));
create or replace function public.renqd_invite_notes_collaborator(p_resource_type text,p_resource_id uuid,p_username text) returns uuid language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare v_actor uuid:=auth.uid();v_target uuid;v_title text;v_invite_id uuid;v_resource_type text:=upper(trim(p_resource_type));v_actor_username text;v_can_manage boolean:=false;
begin
if v_actor is null or not private.is_approved_user() then raise exception 'Account non autorizzato' using errcode='42501';end if;
if v_resource_type not in('FOLDER','DOCUMENT') then raise exception 'Tipo di contenuto non valido';end if;
select id into v_target from public.profiles where lower(username)=lower(trim(p_username)) and status::text='APPROVED';
if v_target is null then raise exception 'Utente Renqd non trovato o non approvato';end if;
if v_target=v_actor then raise exception 'Non puoi invitare te stesso';end if;
select username into v_actor_username from public.profiles where id=v_actor;
if v_resource_type='FOLDER' then select title into v_title from public.notes_folders where id=p_resource_id;v_can_manage:=private.notes_can_manage_folder(p_resource_id,v_actor);
else select title into v_title from public.notes_documents where id=p_resource_id;v_can_manage:=exists(select 1 from public.notes_documents d where d.id=p_resource_id and d.owner_id=v_actor) or exists(select 1 from public.notes_documents d where d.id=p_resource_id and d.folder_id is not null and private.notes_can_manage_folder(d.folder_id,v_actor));end if;
if not v_can_manage then raise exception 'Solo il proprietario può gestire gli inviti' using errcode='42501';end if;
if v_resource_type='FOLDER' then insert into public.notes_collaborators(resource_type,folder_id,owner_id,invited_user_id,invited_by,status) values('FOLDER',p_resource_id,v_actor,v_target,v_actor,'PENDING') on conflict(folder_id,invited_user_id) where resource_type='FOLDER' do update set invited_by=excluded.invited_by,owner_id=excluded.owner_id,status='PENDING',responded_at=null,created_at=now() returning id into v_invite_id;
else insert into public.notes_collaborators(resource_type,document_id,owner_id,invited_user_id,invited_by,status) values('DOCUMENT',p_resource_id,v_actor,v_target,v_actor,'PENDING') on conflict(document_id,invited_user_id) where resource_type='DOCUMENT' do update set invited_by=excluded.invited_by,owner_id=excluded.owner_id,status='PENDING',responded_at=null,created_at=now() returning id into v_invite_id;end if;
insert into public.user_notifications(recipient_id,actor_id,notification_type,payload) values(v_target,v_actor,'NOTES_INVITATION',jsonb_build_object('inviteId',v_invite_id,'resourceType',v_resource_type,'resourceId',p_resource_id,'resourceTitle',v_title,'actorUsername',v_actor_username));return v_invite_id;end;$$;